<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use App\Models\{User,WebPushSubscription};
use Illuminate\Validation\ValidationException;
class NotificationController extends Controller {
 private function approved(Request $r):void{abort_unless($r->user()?->status==='approved',403,'ပိုင်ရှင်အတည်ပြုချက်ကို စောင့်ပါ။');}
 public function index(Request $r){$this->approved($r);$r->validate(['page'=>'sometimes|integer|min:1|max:1000000','summary'=>'sometimes|boolean']);$base=DB::table('shop_notifications')->where('recipient_id',$r->user()->id);$summary=['unread_count'=>(clone $base)->whereNull('read_at')->count(),'latest_id'=>(int)((clone $base)->max('id')??0)];if($r->boolean('summary'))return response()->json($summary);
  $q=(clone $base)->orderByDesc('id');$page=$q->paginate(10);if($page->currentPage()>$page->lastPage())$page=$q->paginate(10,['*'],'page',$page->lastPage());
  $rows=$page->getCollection()->map(function($row){foreach(['created_at','read_at'] as $key)if($row->$key)$row->$key=\Carbon\Carbon::parse($row->$key,config('app.timezone'))->toIso8601String();unset($row->recipient_id,$row->updated_at);return $row;});
  return response()->json([...$summary,'data'=>$rows,'meta'=>['current_page'=>$page->currentPage(),'last_page'=>$page->lastPage(),'per_page'=>10,'total'=>$page->total(),'from'=>$page->firstItem(),'to'=>$page->lastItem()]]);
 }
 public function read(Request $r,int $notification){$this->approved($r);$q=DB::table('shop_notifications')->where('id',$notification)->where('recipient_id',$r->user()->id);abort_unless((clone $q)->exists(),404);$q->whereNull('read_at')->update(['read_at'=>now(),'updated_at'=>now()]);return response()->json(['ok'=>true]);}
 public function readAll(Request $r){$this->approved($r);$r->validate(['through_id'=>'required|integer|min:1']);DB::table('shop_notifications')->where('recipient_id',$r->user()->id)->where('id','<=',$r->integer('through_id'))->whereNull('read_at')->update(['read_at'=>now(),'updated_at'=>now()]);return response()->json(['ok'=>true]);}
 public function settings(Request $r){$this->approved($r);return response()->json(['public_key'=>config('webpush.public_key'),'configured'=>(bool)(config('webpush.public_key')&&config('webpush.private_key'))]);}
 public function status(Request $r){$this->approved($r);$v=$r->validate(['endpoint'=>'required|string|max:2048']);return response()->json(['enabled'=>WebPushSubscription::where('user_id',$r->user()->id)->where('endpoint_hash',hash('sha256',$v['endpoint']))->exists()]);}
 public function subscribe(Request $r){$this->approved($r);abort_unless(config('webpush.public_key')&&config('webpush.private_key'),503,'အသိပေးချက်ဝန်ဆောင်မှု အသင့်မဖြစ်သေးပါ။');$v=$r->validate(['endpoint'=>'required|string|max:2048','keys.p256dh'=>'required|string|max:120','keys.auth'=>'required|string|max:40']);$url=parse_url($v['endpoint']);$host=strtolower($url['host']??'');$allowed=in_array($host,['fcm.googleapis.com','android.googleapis.com','updates.push.services.mozilla.com','push.services.mozilla.com','web.push.apple.com'])||str_ends_with($host,'.push.services.mozilla.com')||str_ends_with($host,'.push.apple.com')||str_ends_with($host,'.notify.windows.com');
  if(!$allowed||($url['scheme']??'')!=='https'||isset($url['user'])||isset($url['pass'])||isset($url['fragment'])||(isset($url['port'])&&$url['port']!==443))throw ValidationException::withMessages(['endpoint'=>'အသိပေးချက်လိပ်စာ မမှန်ပါ။']);
  $decode=fn($value)=>preg_match('/^[A-Za-z0-9_-]+$/D',$value)?base64_decode(strtr($value,'-_','+/'),true):false;$public=$decode($v['keys']['p256dh']);$auth=$decode($v['keys']['auth']);if($public===false||strlen($public)!==65||ord($public[0])!==4||$auth===false||strlen($auth)!==16)throw ValidationException::withMessages(['keys'=>'အသိပေးချက်သော့ မမှန်ပါ။']);
  return DB::transaction(function()use($r,$v){User::where('id',$r->user()->id)->lockForUpdate()->first();$hash=hash('sha256',$v['endpoint']);$existing=WebPushSubscription::where('endpoint_hash',$hash)->first();if((!$existing||$existing->user_id!==$r->user()->id)&&WebPushSubscription::where('user_id',$r->user()->id)->count()>=10)abort(422,'အသိပေးချက်ဖွင့်ထားသော စက် ၁၀ လုံး ပြည့်နေပါပြီ။');WebPushSubscription::updateOrCreate(['endpoint_hash'=>$hash],['user_id'=>$r->user()->id,'endpoint'=>$v['endpoint'],'public_key'=>$v['keys']['p256dh'],'auth_token'=>$v['keys']['auth']]);return response()->json(['enabled'=>true]);},3);
 }
 public function test(Request $r){$this->approved($r);app(\App\Services\ShopNotifications::class)->record($r->user()->id,'push_enabled','အသိပေးချက် ဖွင့်ထားပါပြီ','အဲအဲလေးမှ အသိပေးချက်များ ရနိုင်ပါပြီ။','dashboard');return response()->json(['ok'=>true]);}
 public function unsubscribe(Request $r){$this->approved($r);$v=$r->validate(['endpoint'=>'required|string|max:2048']);WebPushSubscription::where('user_id',$r->user()->id)->where('endpoint_hash',hash('sha256',$v['endpoint']))->delete();return response()->json(['enabled'=>false]);}
}
